INSERT INTO `chapitres` VALUES (1,'T.111.111','DWB-T.111.111','Identifier le contexte et les acteurs','https://solicode-web-mobile.github.io/autoformations-web/tutos/identifier-contexte-acteurs/','<p>Comprendre une application à partir de ses maquettes et identifier sa finalité, son périmètre et ses acteurs.</p><p>Prérequis : Les maquettes du Blog personnel sont nécessaires.</p>',1,1,1,1,NULL,'2026-09-07 06:32:42','2026-09-07 06:33:08',0),(2,'T.112.111','DWB-T.112.111','Rôle des données dans une application','https://solicode-web-mobile.github.io/autoformations-web/tutos/r%C3%B4le-donn%C3%A9es/','Comprendre la différence entre information et donnée, et comprendre pourquoi une application utilise des données pour réaliser une fonctionnalité.',1,1,1,2,NULL,'2026-09-07 06:32:42','2026-09-07 06:33:08',0),(3,'T.121.111','DWB-T.121.111','Afficher son nom avec JavaScript','https://solicode-web-mobile.github.io/autoformations-web/tutos/variables-entr%C3%A9es-sorties/','Découvrir JavaScript et Node.js, puis créer et exécuter un programme qui affiche votre nom dans la console.',1,1,1,3,NULL,'2026-09-07 06:32:43','2026-09-07 06:33:08',0),(4,'T.161.11','DWB-T.161.11','Découvrir Google Slides et le partage','https://solicode-web-mobile.github.io/autoformations-web/tutos/partage-google-slides/','Créer une présentation d’une slide pour présenter son profil, puis la partager avec un lien afin que d’autres personnes puissent la consulter.',1,1,1,5,NULL,'2026-09-07 06:32:43','2026-09-07 06:32:43',0),(5,'T.162.111','DWB-T.162.111','Comment apprendre à Solicode ?','https://solicode-web-mobile.github.io/autoformations-web/tutos/apprendre-%C3%A0-solicode/',NULL,1,1,1,9,NULL,'2026-09-07 06:32:43','2026-09-07 06:32:43',0),(6,'T.161.121','DWB-T.161.121','Découvrir le Web et Internet','https://solicode-web-mobile.github.io/autoformations-web/tutos/web-internet/','Comprendre Internet, le Web, le navigateur, le site Web et l’application Web.',1,2,1,6,NULL,'2026-09-07 06:32:43','2026-09-07 06:33:08',0),(7,'T.121.112','DWB-T.121.112','Manipuler les variables','https://solicode-web-mobile.github.io/autoformations-web/tutos/manipuler-variables/','Comprendre ce qu’est une variable et l’utiliser pour stocker et afficher des valeurs en JavaScript.',1,2,1,3,NULL,'2026-09-07 06:32:43','2026-09-07 06:32:43',0),(8,'T.161.131','DWB-T.161.131','Découvrir les langages du Web','https://solicode-web-mobile.github.io/autoformations-web/tutos/langages-du-web/',NULL,1,3,1,7,NULL,'2026-09-07 06:32:43','2026-09-07 06:33:08',0),(9,'T.121.113','DWB-T.121.113','Effectuer des opérations','https://solicode-web-mobile.github.io/autoformations-web/tutos/effectuer-operations','Utiliser les opérations arithmétiques en JavaScript pour calculer un résultat avec des variables.',1,3,1,3,NULL,'2026-09-07 06:32:43','2026-09-07 06:32:43',0),(10,'T.161.141','DWB-T.161.141','Découvrir le métier de développeur','https://solicode-web-mobile.github.io/autoformations-web/tutos/m%C3%A9tier-d%C3%A9veloppeur/',NULL,1,4,1,8,NULL,'2026-09-07 06:32:43','2026-09-07 06:33:08',0),(11,'T.121.114','DWB-T.121.114','Recevoir des données','https://solicode-web-mobile.github.io/autoformations-web/tutos/recevoir-donnees/',NULL,1,4,1,3,NULL,'2026-09-07 06:32:43','2026-09-07 06:32:43',0),(12,'T.121.115','DWB-T.121.115','Exercice : gérer un article','https://solicode-web-mobile.github.io/autoformations-web/tutos/exercice-gerer-article/',NULL,1,5,1,3,NULL,'2026-09-07 06:32:43','2026-09-07 06:32:43',0),(13,'T.121.116','DWB-T.121.116','Échanger deux variables','https://solicode-web-mobile.github.io/autoformations-web/tutos/echanger-deux-variables','Découvrir une première technique algorithmique en JavaScript : échanger les valeurs de deux variables sans les perdre.',1,6,1,3,NULL,'2026-09-07 06:32:43','2026-09-07 06:32:43',0);
