INSERT INTO `competences` VALUES (1,'C.162',NULL,'Pédagogie active',NULL,'2026-09-07 06:32:13','2026-09-07 06:32:13',8,'DWB-M105-C.162'),(2,'C.122',NULL,'Construire l’interface','Interpréter une conception structurer avec HTML appliquer une présentation CSS afficher les informations nécessaires sélectionner et manipuler les éléments réagir aux actions utilisateur modifier dynamiquement l’interface observer corriger et vérifier.','2026-09-07 06:32:13','2026-09-07 06:32:13',11,'DWB-M108-C.122'),(3,'C.112',NULL,'Modéliser les données','Modéliser les données nécessaires à un périmètre fonctionnel défini afin de produire une représentation structurée et cohérente exploitable pour préparer son implémentation.','2026-09-07 06:32:13','2026-09-07 06:32:13',9,'DWB-M106-C.112'),(4,'C.111',NULL,'Analyser un besoin existant','Analyser un besoin logiciel fourni afin d’identifier les acteurs les actions les fonctionnalités et les comportements attendus d’un périmètre fonctionnel défini.','2026-09-07 06:32:13','2026-09-07 06:32:13',9,'DWB-M106-C.111'),(5,'C.121',NULL,'Construire le traitement logique','Identifier les données et résultats attendus décomposer les étapes construire des traitements séquentiels conditionnels répétitifs avec tableaux collections et fonctions simples combiner des traitements exécuter observer comparer corriger et vérifier.','2026-09-07 06:32:13','2026-09-07 06:32:13',8,'DWB-M105-C.121'),(6,'C.131',NULL,'Vérifier une solution','Vérifier manuellement qu’une fonctionnalité produit le comportement attendu identifier et décrire une anomalie simple reproduire le problème dans les mêmes conditions vérifier une correction simple et signaler un problème dépassant son niveau d’intervention.','2026-09-07 06:32:13','2026-09-07 06:32:13',12,'DWB-M109-C.131'),(7,'C.161',NULL,'Veille technologique',NULL,'2026-09-07 06:32:13','2026-09-07 06:32:13',14,'DWB-M111-C.161'),(8,'C.141',NULL,'Mettre une application en service localement','Mettre une application Web en service dans un environnement local connu en suivant une procédure définie. Identifier les prérequis vérifier le serveur Web PHP et la base de données placer les fichiers appliquer les paramètres démarrer les services accéder à l’application vérifier son fonctionnement appliquer une correction connue et signaler un problème dépassant son autonomie.','2026-09-07 06:32:13','2026-09-07 06:32:13',15,'DWB-M112-C.141'),(9,'C.152',NULL,'Organiser et rendre visible son travail','Comprendre l’objectif d’une tâche identifier le résultat attendu la décomposer en étapes simples déterminer un ordre logique suivre les étapes réalisées et restantes mettre à jour l’avancement identifier et signaler une difficulté rendre compte du travail réalisé et de l’état final.','2026-09-07 06:32:13','2026-09-07 06:32:13',10,'DWB-M107-C152'),(10,'C.151',NULL,'Versionner son propre travail','Cloner ou initialiser un dépôt identifier l’état des fichiers préparer les modifications créer des commits cohérents rédiger des messages explicites consulter l’historique récupérer et envoyer des modifications retrouver une version antérieure reprendre le travail dans un autre environnement et vérifier la synchronisation.','2026-09-07 06:32:13','2026-09-07 06:32:13',10,'DWB-M107-C.151'),(11,'C.125',NULL,'Structurer et déboguer une solution','Structurer progressivement le code d’une solution Web et utiliser les outils de débogage pour suivre son exécution observer les variables localiser les problèmes simples et appliquer des corrections adaptées au niveau N1.','2026-09-07 06:32:13','2026-09-07 06:32:13',11,'DWB-M108-C.125'),(12,'C.124',NULL,'Exploiter les données','Identifier les tables clés et relations écrire des requêtes SQL simples sélectionner filtrer trier récupérer des données liées exploiter les résultats en PHP alimenter une fonctionnalité identifier et corriger une erreur simple puis vérifier le résultat.','2026-09-07 06:32:13','2026-09-07 06:32:13',12,'DWB-M109-C.124'),(13,'C.123',NULL,'Réaliser le traitement serveur','Identifier les tables clés et relations écrire des requêtes SQL simples sélectionner filtrer trier récupérer des données liées exploiter les résultats en PHP alimenter une fonctionnalité identifier et corriger une erreur simple puis vérifier le résultat.','2026-09-07 06:32:13','2026-09-07 06:32:13',12,'DWB-M109-C.123');
/*!40000 ALTER TABLE `competences` ENABLE KEYS */;
