INSERT INTO `micro_competences` VALUES (1,'DWB-D.162.1','Apprendre avec la pédagogie active',NULL,'D.162.1',NULL,'<div>S\'approprier les principes de la pédagogie active, l\'apprentissage par projets&nbsp;</div><div>&nbsp; et le travail par les pairs afin de développer son autonomie, structurer sa&nbsp;</div><div>&nbsp; démarche de résolution de problèmes et progresser efficacement au sein de Solicode.</div>',1,1,'2026-09-07 06:32:41','2026-09-07 06:32:41'),(2,'DWB-D.161.1','Technologies de développement',NULL,'D.161.1',NULL,NULL,2,7,'2026-09-07 06:32:41','2026-09-07 06:32:41'),(3,'DWB-D.111.1','Analyser et formaliser un besoin fonctionnel existant',NULL,'D.111.1',NULL,'Analyser un besoin existant afin d’identifier la finalité générale de l’application, son contexte et son périmètre, de repérer les acteurs et leurs rôles, de déterminer leurs actions et de regrouper ces actions en fonctionnalités cohérentes du système.',3,4,'2026-09-07 06:32:41','2026-09-07 06:32:41'),(4,'DWB-D.112.1','Modéliser les données',NULL,'D.112.1',NULL,'Structurer les données nécessaires au fonctionnement d’une application en les identifiant, en les décrivant et en déterminant leurs dépendances, puis en les organisant sous forme d’entités, de relations et de tables à travers le MCD et le MLD.',4,3,'2026-09-07 06:32:41','2026-09-07 06:32:41'),(5,'DWB-D.121.1','Construire le traitement logique',NULL,'D.121.1',NULL,'Construire des traitements JavaScript permettant de manipuler des valeurs, contrôler l’exécution, traiter des collections, réutiliser des fonctions et combiner plusieurs structures de programmation pour résoudre des problèmes algorithmiques simples.',5,5,'2026-09-07 06:32:41','2026-09-07 06:32:41'),(6,'DWB-D.122.1','Structurer une interface avec HTML',NULL,'D.122.1',NULL,'Construire une interface HTML correctement structurée à partir d’une conception existante en organisant le squelette de la page, les contenus, les zones sémantiques, les ensembles répétitifs et les éléments nécessaires à la saisie et à l’envoi de données.',6,2,'2026-09-07 06:32:41','2026-09-07 06:32:41'),(7,'DWB-D.122.2','Mettre en forme une interface avec CSS',NULL,'D.122.2',NULL,'Construire une interface Web correctement mise en forme à partir d’une conception existante en appliquant des règles CSS, en maîtrisant les dimensions et les espacements, en organisant les éléments, en harmonisant leur présentation et en adaptant l’interface aux différentes tailles d’écran.',7,2,'2026-09-07 06:32:41','2026-09-07 06:32:41'),(8,'DWB-D.122.3','Rendre l’interface interactive avec JavaScript',NULL,'D.122.3',NULL,'Construire une interface Web interactive en utilisant JavaScript pour exécuter des traitements simples, sélectionner et modifier les éléments du DOM, gérer les événements utilisateur, contrôler les données saisies et combiner plusieurs interactions.',8,2,'2026-09-07 06:32:41','2026-09-07 06:32:41'),(9,'DWB-D.123.1','Programmer des traitements serveur avec PHP',NULL,'D.123.1',NULL,'<div>\"Réaliser des traitements PHP permettant d’exécuter des traitements côté serveur, manipuler des données, contrôler leur traitement, recevoir des données d’une requête Web et organiser plusieurs opérations dans un traitement serveur cohérent.</div><div>\"</div>',9,13,'2026-09-07 06:32:41','2026-09-07 06:32:41'),(10,'DWB-D.124.1','Interroger une base de données avec SQL',NULL,'D.124.1',NULL,'<div>\"Exploiter les données d’une base de données en créant sa structure à partir du MLD, en sélectionnant, filtrant, triant et limitant les données avec des requêtes SQL, puis en combinant et corrigeant des requêtes simples afin d’obtenir les résultats attendus.</div><div>\"</div>',10,12,'2026-09-07 06:32:41','2026-09-07 06:32:41'),(11,'DWB-D.124.2','Exploiter les résultats et les données dans l’application',NULL,'D.124.2',NULL,'Exploiter les résultats produits par les requêtes SQL dans PHP afin de les utiliser dans l’application, de les afficher dans l’interface, de traiter des critères de recherche, d’exploiter des données issues de tables liées et de vérifier et corriger les problèmes simples rencontrés.',11,12,'2026-09-07 06:32:41','2026-09-07 06:32:41'),(12,'DWB-D.125.1','Structurer le code',NULL,'D.125.1',NULL,'Structurer une solution Web en organisant les fichiers, les ressources, les traitements serveur, l’accès aux données et les différents espaces de l’application selon leur rôle.',12,11,'2026-09-07 06:32:41','2026-09-07 06:32:41'),(13,'DWB-D.125.2','Déboguer et résoudre les erreurs',NULL,'D.125.2',NULL,'Utiliser le débogage pour observer l’exécution d’un programme, localiser une partie de code responsable d’un problème, appliquer une correction ciblée et vérifier le bon fonctionnement du traitement.',13,11,'2026-09-07 06:32:41','2026-09-07 06:32:41'),(14,'DWB-D.131.1','Vérifier le fonctionnement d’une solution',NULL,'D.131.1',NULL,'Vérifier qu’une fonctionnalité produit le résultat attendu et contrôler, après modification, que les fonctionnalités existantes continuent de produire les résultats attendus.',14,6,'2026-09-07 06:32:41','2026-09-07 06:32:41'),(15,'DWB-D.141.1','Déployer une application Web dans un environnement local',NULL,'D.141.1',NULL,'Mettre une application Web en service dans un environnement local connu en préparant les éléments nécessaires à son exécution et en vérifiant son accessibilité, son fonctionnement et son accès aux données.',15,8,'2026-09-07 06:32:41','2026-09-07 06:32:41'),(16,'DWB-D.151.1','Versionner et synchroniser son travail avec Git',NULL,'D.151.1',NULL,'Utiliser Git et GitHub pour enregistrer, consulter, retrouver, synchroniser et récupérer son travail afin de conserver un historique exploitable et un projet récupérable.',16,10,'2026-09-07 06:32:41','2026-09-07 06:32:41'),(17,'DWB-D.152.2','Organiser et rendre visible son travail',NULL,'D.152.2',NULL,'Organiser et suivre une tâche technique simple afin de réaliser le travail dans le temps disponible, rendre son état visible, signaler les difficultés et rendre compte de la contribution réalisée.',17,9,'2026-09-07 06:32:41','2026-09-07 06:32:41');
/*!40000 ALTER TABLE `micro_competences` ENABLE KEYS */;
UNLOCK TABLES;

