INSERT INTO `session_formations` VALUES (1,'DWB-S1','S1','Comprendre le projet et premiers traitements logiques',1,'2026-09-07','2026-09-18',NULL,NULL,'Découvrir le fonctionnement d’une application Web comprendre le projet cible identifier son contexte et ses acteurs et construire les premiers traitements JavaScript dans le Sandbox Algorithmique.','L’apprenant découvre le projet cible avant toute réalisation technique. Il analyse le contexte du Blog personnel sa finalité son périmètre et ses principaux acteurs. Il découvre le rôle des données dans une application et identifie les premières données nécessaires à son fonctionnement. Il construit en parallèle un premier traitement JavaScript dans le Sandbox Algorithmique. Les principaux outils utilisés pendant la formation sont également découverts à travers des Labs.','Identifier le contexte et les acteurs du Portfolio','Réaliser une première analyse du Portfolio de l’apprenant. Définir son contexte, identifier ses acteurs et préciser les principales fonctionnalités réalisées par chaque acteur.','<div>Livrables :&nbsp;</div><ul><li>✓\nContexte du Portfolio\n</li><li>✓\nListe des acteurs\n</li><li>✓\nActions principales de chaque acteur</li></ul>','Identifier le contexte et les acteurs de projet fil rouge','Réaliser une première analyse du projet fil rouge de l’apprenant. Définir son contexte, identifier ses acteurs et préciser les principales fonctionnalités réalisées par chaque acteur.','<div>Livrables :&nbsp;</div><ul><li>✓ Contexte</li><li>✓ Liste des acteurs</li><li>✓ Actions principales de chaque acteur</li></ul>',1,2,'2026-09-07 06:32:48','2026-09-07 06:32:48');
/*!40000 ALTER TABLE `session_formations` ENABLE KEYS */;
UNLOCK TABLES;

